T="""<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Lift-Lap resort review</title><style>body{font:16px system-ui;max-width:1200px;margin:auto;padding:20px;background:#f7faf4;color:#183b3a}.warn{border-left:5px solid #b54112;padding:12px;background:#fff6ed}.grid{display:grid;grid-template-columns:280px 1fr;gap:20px}.box{background:white;border:1px solid #cbdad0;padding:16px;border-radius:8px}.map{width:100%;min-width:600px;height:560px}.wrap{overflow:auto;border:1px solid #cbdad0}.e{fill:none;stroke-width:2;cursor:pointer;vector-effect:non-scaling-stroke}.lift{stroke:#203f3f;stroke-dasharray:7 5}.piste{stroke:#326f9c}.selected{stroke:#b54112!important;stroke-width:6}.dis{opacity:.25}.pill{display:inline-block;background:#e8f1eb;border-radius:9px;padding:4px;margin:3px}dt{font-weight:bold;margin-top:8px}dd{margin:0;color:#55706b;overflow-wrap:anywhere}a{color:#b54112}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style><main><h1>Resort data review</h1><p class="warn"><b>Browse-only research preview.</b> Unreviewed geometry; not a route selector. No routing, access, direction, operating, timing, safety, or coverage claims. Do not use for navigation.</p><div class="grid"><aside class="box"><label for="s">Research sample</label><select id="s"></select><p><label><input id="l" type="checkbox" checked> Lifts</label><br><label><input id="p" type="checkbox" checked> Pistes</label><br><label><input id="d" type="checkbox" checked> Disconnected</label></p><p id="cov"></p></aside><section class="box"><h2>Source geometry</h2><div id="sum"></div><div class="wrap"><svg id="map" class="map" viewBox="0 0 900 560" role="img" aria-label="Unreviewed resort geometry"></svg></div><p id="status" role="status" aria-live="polite">Select a segment.</p><div id="detail" tabindex="-1"></div></section></div><section class="box"><h2>Source and review limits</h2><p id="src"></p><p>Native grade is the original OSM tag, not a cross-resort guarantee. Disconnected is structural, not evidence of a connector. Source links are explicit user actions. © OpenStreetMap contributors; ODbL 1.0. This artifact makes no network requests.</p></section></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector("#data").textContent),$=x=>document.getElementById(x);let C,E;function comps(g){let a=new Map(g.nodes.map(n=>[n.id,new Set()]));g.edges.forEach(e=>{a.get(e.from)?.add(e.to);a.get(e.to)?.add(e.from)});let r=new Map,s=new Set,c=0;for(let n of g.nodes){if(s.has(n.id))continue;c++;let q=[n.id];s.add(n.id);while(q.length){let x=q.pop();r.set(x,c);for(let y of a.get(x)||[]){if(!s.has(y)){s.add(y);q.push(y)}}}}return r}function detail(e){E=e.id;draw();let d=$("detail");d.replaceChildren();let b=document.createElement("b");b.textContent=e.name||e.id;d.append(b);let dl=document.createElement("dl");for(let x of [["Kind",e.kind],["Native grade",e.source_difficulty||"unknown"],["Normalized grade",e.difficulty||"unknown"],["Source way",e.source_refs?.[0]||"unknown"],["Review status",e.review_status||C.graph.review_status],["Direction",e.from+" → "+e.to]]){let a=document.createElement("dt"),b=document.createElement("dd");a.textContent=x[0];b.textContent=x[1];dl.append(a,b)}let a=document.createElement("a");a.href="https://www.openstreetmap.org/"+(e.source_refs?.[0]||"");a.target="_blank";a.rel="noopener noreferrer";a.textContent="Open source way";dl.append(a);d.append(dl);d.focus()}function draw(){let g=C.graph,m=C.manifest,v=$("map");v.replaceChildren();let X=g.nodes.map(n=>n.lon),Y=g.nodes.map(n=>n.lat),a=Math.min(...X),b=Math.max(...X),c=Math.min(...Y),d=Math.max(...Y),z=Math.min(790/(b-a),470/(d-c)),f=([x,y])=>[55+(x-(a+b)/2)*z,280-(y-(c+d)/2)*z],cc=comps(g);for(let e of g.edges.filter(e=>e.kind=="lift"?$("l").checked:$("p").checked)){let q=document.createElementNS("http://www.w3.org/2000/svg","polyline");q.setAttribute("points",e.geometry.map(f).map(x=>x.join(",")).join(" "));q.setAttribute("class","e "+e.kind+(E==e.id?" selected":"")+( $("d").checked&&cc.get(e.from)!=cc.get(e.to)?" dis":""));q.setAttribute("tabindex","0");q.setAttribute("role","button");q.setAttribute("aria-label",(e.name||e.id)+", native grade "+(e.source_difficulty||"unknown"));q.onclick=()=>detail(e);q.onkeydown=x=>{if(x.key=="Enter"||x.key==" "){x.preventDefault();detail(e)}};v.append(q)}$("sum").textContent="Nodes: "+g.nodes.length+" · Edges: "+g.edges.length+" · Lifts: "+g.edges.filter(e=>e.kind=="lift").length+" · Pistes: "+g.edges.filter(e=>e.kind=="piste").length+" · Weak components: "+new Set(cc.values()).size;$("cov").textContent="Bounded coverage: "+m.coverage_status;$("src").textContent="Fetched "+m.fetched_at+" · "+m.attribution+" · graph "+m.graph_sha256}for(let k in D){let o=document.createElement("option");o.value=k;o.textContent=D[k].label;$("s").append(o)}function load(){C=D[$("s").value];E=null;draw()}$("s").onchange=load;for(let x of ["l","p","d"])$(x).onchange=draw;load();</script>"""
